-- PRD-12 -- SELESAI. Implementasi persis sesuai keputusan final pemilik
-- produk (blokir keras + jalan keluar beralasan, append-only).
update public.build_tasks
set status = 'selesai', completed_at = now(),
    detail_pekerjaan = detail_pekerjaan || E'\n\n---\n\nDITUTUP 22 Agu 2026. Diimplementasikan PERSIS sesuai keputusan final: planned->in_progress OTOMATIS di startProductionBatch.ts (saat batch pertama dimulai); ->completed/paused/cancelled MANUAL lewat setWorkOrderStatus.ts (paused/cancelled wajib alasan, disimpan di kolom work_orders.status_reason); pagar keamanan createProductionBatch.ts (SUDAH ada sejak awal, kini benar-benar aktif) menolak batch baru pada WO completed/cancelled; reopenWorkOrder.ts -- gerbang company_admin/production_manager SAJA (bukan general_manager/ppic_manager, sesuai kata "manajer produksi" eksplisit), wajib alasan, riwayat APPEND-ONLY di tabel baru work_order_reopen_log (tidak ada jalur update/delete sama sekali, bahkan dari service-role). TIDAK ADA layar baru dibangun (sesuai batas) -- kolom STATUS yang sudah ada di WorkOrdersPage.tsx/ProductionDashboardPage.tsx SUDAH punya label+warna utk kelima status sejak awal (ternyata sudah diantisipasi), jadi otomatis benar begitu field-nya hidup, dibuktikan visual di company.b@debug.mrp (badge "Berjalan" tampil kuning, terpisah dari Kesiapan). WO lama (2 baris, semua "planned") TIDAK disentuh migrasi -- berpindah sendiri lewat aturan baru. Bukti lengkap (a)-(e) di tests/prd12_work_order_status_lifecycle.test.ts (5/5 lulus).'
where task_code = 'PRD-12';
